// Service Interface
public interface IInventoryService
{
    Task AddStock(int warehouseId, int productId, decimal quantity);
    Task<bool> RemoveStock(int warehouseId, int productId, decimal quantity);
    Task<IEnumerable<InventoryItem>> GetInventory();
    Task<IEnumerable<InventoryItem>> GetInventoryByWarehouse(int warehouseId);
}

// Service Implementation
public class InventoryService : IInventoryService
{
    private readonly InventoryContext _context;

    public InventoryService(InventoryContext context)
    {
        _context = context;
    }

    public async Task AddStock(int warehouseId, int productId, decimal quantity)
    {
        var inventoryItem = await _context.InventoryItems
            .FirstOrDefaultAsync(ii => ii.WarehouseId == warehouseId && ii.ProductId == productId);

        if (inventoryItem != null)
        {
            inventoryItem.Quantity += quantity;
            inventoryItem.LastUpdated = DateTime.UtcNow;
        }
        else
        {
            inventoryItem = new InventoryItem
            {
                WarehouseId = warehouseId,
                ProductId = productId,
                Quantity = quantity,
                LastUpdated = DateTime.UtcNow
            };
            await _context.InventoryItems.AddAsync(inventoryItem);
        }

        await _context.SaveChangesAsync();
    }

    public async Task<bool> RemoveStock(int warehouseId, int productId, decimal quantity)
    {
        var inventoryItem = await _context.InventoryItems
            .FirstOrDefaultAsync(ii => ii.WarehouseId == warehouseId && ii.ProductId == productId);

        if (inventoryItem == null || inventoryItem.Quantity < quantity)
            return false;

        inventoryItem.Quantity -= quantity;
        inventoryItem.LastUpdated = DateTime.UtcNow;

        await _context.SaveChangesAsync();
        return true;
    }

    public async Task<IEnumerable<InventoryItem>> GetInventory()
    {
        return await _context.InventoryItems
            .Include(ii => ii.Product)
            .Include(ii => ii.Warehouse)
            .ToListAsync();
    }

    public async Task<IEnumerable<InventoryItem>> GetInventoryByWarehouse(int warehouseId)
    {
        return await _context.InventoryItems
            .Include(ii => ii.Product)
            .Where(ii => ii.WarehouseId == warehouseId)
            .ToListAsync();
    }
}
